def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

def counts(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            X[i, j] = float((i * 31 + j * 17 + i * j * 7 + y[i] * (j + 1)) % 6)
    return X, y

def close(got, exp: List[float], rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if np.isnan(exp[i]):
            if not np.isnan(g[i]):
                print("mismatch at", i, g[i], exp[i])
                return False
            continue
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

def eqi(got, exp: List[int]) -> bool:
    g = np.asarray(got).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if int(g[i]) != exp[i]:
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

failed = 0
def check(ok: bool, name: str):
    global failed
    if not ok:
        print("TEST FAILED:", name)
        failed += 1

X0, y = data(60, 4, 3)
yr = X0[:, 0] * 2.0 - X0[:, 1] + 0.5 * y
X = X0.copy()
for i in range(60):
    for j in range(4):
        X[i, j] += 0.01 * np.sin(float(i * 4 + j))
Q = X[:7] + 0.13

def nn_case(metric: str, p: float, ed: List[float], ei: List[int], name: str):
    nn = NearestNeighbors(n_neighbors=4, metric=metric, p=p, algorithm="brute").fit(X)
    d, i = nn.kneighbors(Q)
    check(close(d, ed), name + " dist")
    check(eqi(i, ei), name + " ind")
    # every algorithm gives identical results
    nb = NearestNeighbors(n_neighbors=4, metric=metric, p=p, algorithm="ball_tree").fit(X)
    check(eqi(nb.kneighbors(Q, return_distance=False), ei), name + " ball_tree")

