nn_case("minkowski", 1.0, nn_d_minkowski_1, nn_i_minkowski_1, "nn l1")
nn_case("minkowski", float("inf"), nn_d_minkowski_inf, nn_i_minkowski_inf, "nn linf")
nn_case("minkowski", 3.0, nn_d_minkowski_3, nn_i_minkowski_3, "nn l3")
nn_case("cosine", 2.0, nn_d_cosine_2, nn_i_cosine_2, "nn cosine")
