d, i = nn.kneighbors()
check(close(d[:5], nn_self_d), "self dist")
check(eqi(i[:5], nn_self_i), "self ind")
check(close(nn.kneighbors_graph(Q[:3], mode="distance"), nn_graph), "graph")
