check(close(rd[0], rn_d0) and close(rd[1], rn_d1) and close(rd[2], rn_d2), "radius dist")
check(eqi(ri[0], rn_i0) and eqi(ri[1], rn_i1) and eqi(ri[2], rn_i2), "radius ind")

