check(close([c.score(X, y)], [knc_score_uniform]), "knc score u")
c2 = KNeighborsClassifier(n_neighbors=5, weights="distance").fit(X, y)
check(close(c2.predict_proba(Q), knc_proba_distance), "knc proba d")
check(eqi(c2.predict(Q), knc_pred_distance), "knc pred d")
check(close([c2.score(X, y)], [knc_score_distance]), "knc score d")
